// Project the production pool instrument's computed positions onto the vertical tube.
// In particular, aria-valuenow is progress to the guarantee, NOT the expanded scale.
const clamp = value => Math.max(0, Math.min(100, value));
export function syncVerticalPoolScale(source, thermometer, { jackpot = false, jackpotPercent = 100, purchasePreview = null } = {}) {
  const track = thermometer.querySelector('.concept-track');
  const nativeTrack = source.querySelector('[data-el="pool-track"]');
  const ready = !jackpot && (purchasePreview ? purchasePreview.levelReady : nativeTrack?.classList.contains('is-ready'));
  const over = !jackpot && (purchasePreview ? purchasePreview.growthOver : nativeTrack?.classList.contains('is-over-growth'));
  const dayText=source.querySelector(`[data-el="${jackpot?'pool-jackpot-day':'pool-day'}"]`)?.textContent||'';
  const dayMatch=jackpot?dayText.match(/^(\d+)/):dayText.match(/PURCHASE DAY (\d+)/i);
  const day=purchasePreview?1:dayMatch?Number(dayMatch[1]):null;
  const percent = jackpot ? clamp(jackpotPercent) : clamp(purchasePreview?.fillPercent ?? (parseFloat(source.querySelector('[data-el="pool-fill"]')?.style.width) || 0));
  track.style.setProperty('--site-pool-fill', `${percent}%`);
  track.dataset.scale = jackpot?'jackpot':ready?'expanded':'progression';
  track.classList.toggle('is-over-growth', Boolean(over));
  const goal=source.querySelector('[data-el="pool-target-marker"]');
  const goalPosition=purchasePreview ? purchasePreview.targetPercent : parseFloat(goal?.style.left);
  const goalHidden=purchasePreview ? purchasePreview.target == null : goal?.hidden;
  const dayPercent=Number.isFinite(goalPosition)?clamp((day??0)/30*100)*clamp(goalPosition)/100:0;
  let dayFill=track.querySelector('.site-pool-day-fill');
  if(!dayFill){dayFill=document.createElement('span');dayFill.className='site-pool-day-fill';dayFill.setAttribute('aria-hidden','true');track.append(dayFill);}
  dayFill.hidden=jackpot||ready||day==null||goalHidden||!Number.isFinite(goalPosition);
  dayFill.style.height=`calc(${dayPercent}% - ${dayPercent*.04}px)`;
  for (const [kind, nativeName] of [['goal','pool-target-marker'],['growth','pool-growth-marker']]) {
    let marker = track.querySelector(`[data-pool-marker="${kind}"]`);
    if (!marker) {
      marker = document.createElement('span');
      marker.className = `site-pool-marker site-pool-marker--${kind}`;
      marker.dataset.poolMarker = kind;
      marker.setAttribute('role', 'img');
      marker.innerHTML='<span class="site-pool-marker__label"><small></small><span><strong></strong> <small>ETH</small></span></span>';
      track.append(marker);
    }
    const native = source.querySelector(`[data-el="${nativeName}"]`);
    const position = purchasePreview ? (kind==='goal'?purchasePreview.targetPercent:purchasePreview.growthPercent) : parseFloat(native?.style.left);
    const title = purchasePreview ? (kind==='goal'?purchasePreview.targetTitle:purchasePreview.growthTitle) : native?.title;
    const hidden = purchasePreview ? position == null : !native || native.hidden;
    marker.hidden = jackpot || (kind==='goal'?ready:!ready||over) || hidden || !Number.isFinite(position);
    marker.tabIndex = marker.hidden ? -1 : 0;
    marker.title = title || '';
    marker.setAttribute('aria-label', marker.title);
    marker.querySelector('.site-pool-marker__label>small').textContent=kind==='goal'?'POOL TARGET':'OVER / UNDER';
    const amount=marker.title.match(/· ([\d,.]+) ETH/)?.[1];
    marker.querySelector('strong').textContent=amount?Number(amount.replaceAll(',','')).toLocaleString('en-US',{maximumFractionDigits:0}):'—';
    if (!marker.hidden) marker.style.bottom = `calc(${clamp(position)}% + ${2 - clamp(position) * .04}px)`;
  }
  let history = track.querySelector('.site-pool-history');
  if (!history) { history = document.createElement('span'); history.className = 'site-pool-history'; track.append(history); }
  const ticks = ready && !purchasePreview ? [...source.querySelectorAll('[data-el="pool-history-markers"] > [data-level]')] : [];
  const signature = ticks.map(tick => `${tick.dataset.level}:${tick.style.left}:${tick.title}`).join('|');
  if (history.dataset.signature !== signature) {
    history.dataset.signature = signature;
    history.replaceChildren(...ticks.map(tick => {
      const mark = document.createElement('span');
      mark.className = 'site-pool-history__tick';mark.tabIndex = 0;mark.title = tick.title;
      mark.setAttribute('role','img');mark.setAttribute('aria-label',tick.title);
      const position = clamp(parseFloat(tick.style.left));
      mark.style.bottom = `calc(${position}% + ${2 - position * .04}px)`;
      return mark;
    }));
  }
  return { percent, ready, over, day, dayPercent,
    targetTitle:purchasePreview?.targetTitle ?? source.querySelector('[data-el="pool-target-marker"]')?.title ?? '',
    growthTitle:purchasePreview?.growthTitle ?? source.querySelector('[data-el="pool-growth-marker"]:not([hidden])')?.title ?? '' };
}
